/***************************************************************************//*                                                                         *//* execv() : Unix library (OS9/68000)                                      *//* =======                                                                 *//*                                                                         *//* Compiler:   Microware C                                                 *//* OS:         OS9/68000                                                   *//*                                                                         *//* Edition History                                                         *//* ===============                                                         *//*                                                                         *//* Ed. 0.00  Date 08/22/2026                                               *//*           First version, written for the OS-9 freeware collection.      *//*           execl() was here and execv() was not, which is what stopped    *//*           SRC/adv (advent) from linking.                                *//*                                                                         *//***************************************************************************//*                                                                         *//* Description                                                             *//*                                                                         *//*     SYNOPSIS          int execv (path, argv)          char *path, *argv[];     DESCRIPTION          As execl(), but the arguments are handed over as a vector          already built, terminated by a null pointer, rather than as a          variable-length argument list.  argv[0] is the name the new          process sees as its own.          On success it does not return: the calling process becomes the          new one.  On failure it returns -1 with errno set.*/int execv (path, argv)     char *path, *argv[];     {     extern int errno, chainc(), os9exec(), modload();     extern char **environ;     /* Load the module first, exactly as execl() does: os9exec() chains to      * a module by name, and without this the name may not be in the module      * directory yet. */     modload(path, 0);     exit(os9exec(chainc, argv[0] ? argv[0] : path, argv, environ, 0, 0, 32));     return (-1);        /* not reached */     } /* end of execv */